import { MONTH_DAYS } from '../constants';
import type {
  Expense,
  FinancialState,
  FixedCommitment,
  MonthArchive,
  SavingsGoal,
  SimulatorAction,
  Subscription,
  Template,
} from '../types/finance';

/** Every state change in the app is one of these. IDs are generated by the caller so the reducer stays pure. */
export type BudgetAction =
  | { type: 'replace'; state: FinancialState }
  | { type: 'merge-remote'; state: FinancialState }
  | { type: 'toggle-theme' }
  | { type: 'toggle-panic' }
  | { type: 'toggle-sound' }
  | { type: 'set-day'; day: number }
  | { type: 'set-discord'; webhookUrl?: string; autoPing?: boolean }
  | { type: 'expense/add'; expense: Expense }
  | { type: 'expense/update'; expense: Expense }
  | { type: 'expense/delete'; id: string }
  | { type: 'template/add'; template: Template }
  | { type: 'template/delete'; id: string }
  | { type: 'commitment/add'; item: FixedCommitment }
  | { type: 'commitment/toggle'; id: string }
  | { type: 'commitment/delete'; id: string }
  | { type: 'subscription/add'; item: Subscription }
  | { type: 'subscription/toggle'; id: string }
  | { type: 'subscription/delete'; id: string }
  | { type: 'goal/add'; goal: SavingsGoal }
  | { type: 'goal/update'; goal: SavingsGoal }
  | { type: 'goal/delete'; id: string }
  | { type: 'goal/deposit'; id: string; amount: number }
  | { type: 'goal/withdraw'; id: string; amount: number }
  | { type: 'decision/apply'; action: SimulatorAction; idSeed: string; dailyBurn: number }
  | {
      type: 'month/end';
      archive: MonthArchive;
      newBudget: number;
      carryOver: number;
    }
  | { type: 'history/delete'; id: string };

const clampDay = (d: number) => Math.min(MONTH_DAYS, Math.max(1, d));

export function budgetReducer(state: FinancialState, action: BudgetAction): FinancialState {
  switch (action.type) {
    case 'replace':
      return action.state;
    case 'merge-remote':
      return { ...state, ...action.state };
    case 'toggle-theme':
      return { ...state, theme: state.theme === 'dark' ? 'light' : 'dark' };
    case 'toggle-panic':
      return { ...state, panicModeEnabled: !state.panicModeEnabled };
    case 'toggle-sound':
      return { ...state, soundEnabled: state.soundEnabled === false };
    case 'set-day':
      return { ...state, currentDay: clampDay(action.day) };
    case 'set-discord':
      return {
        ...state,
        discordWebhookUrl: action.webhookUrl ?? state.discordWebhookUrl,
        discordAutoPing: action.autoPing ?? state.discordAutoPing,
      };

    case 'expense/add':
      return { ...state, expenses: [action.expense, ...state.expenses] };
    case 'expense/update':
      return {
        ...state,
        expenses: state.expenses.map((e) => (e.id === action.expense.id ? action.expense : e)),
      };
    case 'expense/delete':
      return { ...state, expenses: state.expenses.filter((e) => e.id !== action.id) };

    case 'template/add':
      return { ...state, templates: [...state.templates, action.template] };
    case 'template/delete':
      return { ...state, templates: state.templates.filter((t) => t.id !== action.id) };

    case 'commitment/add':
      return { ...state, fixedCommitments: [...state.fixedCommitments, action.item] };
    case 'commitment/toggle':
      return {
        ...state,
        fixedCommitments: state.fixedCommitments.map((c) =>
          c.id === action.id ? { ...c, isPaid: !c.isPaid } : c
        ),
      };
    case 'commitment/delete':
      return { ...state, fixedCommitments: state.fixedCommitments.filter((c) => c.id !== action.id) };

    case 'subscription/add':
      return { ...state, subscriptions: [...state.subscriptions, action.item] };
    case 'subscription/toggle':
      return {
        ...state,
        subscriptions: state.subscriptions.map((s) =>
          s.id === action.id ? { ...s, isPaid: !s.isPaid } : s
        ),
      };
    case 'subscription/delete':
      return { ...state, subscriptions: state.subscriptions.filter((s) => s.id !== action.id) };

    case 'goal/add':
      return { ...state, savingsGoals: [...state.savingsGoals, action.goal] };
    case 'goal/update':
      return {
        ...state,
        savingsGoals: state.savingsGoals.map((g) => (g.id === action.goal.id ? action.goal : g)),
      };
    case 'goal/delete':
      return { ...state, savingsGoals: state.savingsGoals.filter((g) => g.id !== action.id) };
    case 'goal/deposit':
      return {
        ...state,
        savingsGoals: state.savingsGoals.map((g) =>
          g.id === action.id ? { ...g, currentAmount: g.currentAmount + action.amount } : g
        ),
      };
    case 'goal/withdraw':
      return {
        ...state,
        savingsGoals: state.savingsGoals.map((g) =>
          g.id === action.id ? { ...g, currentAmount: Math.max(0, g.currentAmount - action.amount) } : g
        ),
      };

    case 'decision/apply':
      return applyDecision(state, action.action, action.idSeed, action.dailyBurn);

    case 'month/end':
      return {
        ...state,
        startingBudget: action.newBudget,
        additionalIncome: action.carryOver,
        currentDay: 1,
        expenses: [],
        history: [action.archive, ...state.history],
      };
    case 'history/delete':
      return { ...state, history: state.history.filter((h) => h.id !== action.id) };
    default:
      return state;
  }
}

function applyDecision(
  state: FinancialState,
  a: SimulatorAction,
  seed: string,
  dailyBurn: number
): FinancialState {
  const day = state.currentDay;
  const asExpense = (title: string, unexpected: boolean): Expense => ({
    id: `exp-${seed}`,
    title: a.title || title,
    amount: a.amount,
    category: a.category,
    dayLogged: day,
    dateString: `Day ${day}`,
    isUnexpected: unexpected,
  });

  switch (a.type) {
    case 'purchase':
      return { ...state, expenses: [asExpense('Simulated Purchase', false), ...state.expenses] };
    case 'surprise':
      return { ...state, expenses: [asExpense('Unexpected Expense', true), ...state.expenses] };
    case 'subscription':
      return {
        ...state,
        subscriptions: [
          ...state.subscriptions,
          {
            id: `sub-${seed}`,
            title: a.title || 'Simulated Subscription',
            amount: a.amount,
            category: a.category,
            dueDay: clampDay(day + 2),
            isPaid: true,
          },
        ],
      };
    case 'bill':
      return {
        ...state,
        fixedCommitments: [
          ...state.fixedCommitments,
          {
            id: `fix-${seed}`,
            title: a.title || 'Simulated Bill',
            amount: a.amount,
            category: a.category,
            dueDay: clampDay(day + 1),
            isPaid: true,
          },
        ],
      };
    case 'savings': {
      if (state.savingsGoals.length > 0) {
        return {
          ...state,
          savingsGoals: state.savingsGoals.map((g, i) =>
            i === 0 ? { ...g, currentAmount: g.currentAmount + a.amount } : g
          ),
        };
      }
      return {
        ...state,
        savingsGoals: [
          {
            id: `goal-${seed}`,
            title: a.title || 'Emergency Stash',
            targetAmount: a.amount * 2,
            currentAmount: a.amount,
          },
        ],
      };
    }
    case 'skip_days': {
      const n = a.daysToSkip || 3;
      const burn: Expense[] = [];
      for (let i = 1; i <= n; i++) {
        const d = clampDay(day + i);
        burn.push({
          id: `exp-burn-${seed}-${i}`,
          title: `Daily burn (Day ${day + i})`,
          amount: dailyBurn,
          category: 'Food & Drink',
          dayLogged: d,
          dateString: `Day ${d}`,
          isUnexpected: false,
        });
      }
      return { ...state, currentDay: clampDay(day + n), expenses: [...burn, ...state.expenses] };
    }
    default:
      return state;
  }
}
